∀ {α : Type u}
  {motive :
    {β : α → Type v} →
      [inst : BEq.{u} α] →
        [inst_1 : Hashable.{u + 1} α] → (a : Std.DHashMap.Raw.{u, v} α β) → Std.DHashMap.Raw.WF.{u, v} a → Prop}
  {β : α → Type v} [inst : BEq.{u} α] [inst_1 : Hashable.{u + 1} α] {a : Std.DHashMap.Raw.{u, v} α β}
  (t : Std.DHashMap.Raw.WF.{u, v} a),
  (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
      (a : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m)))
      (a_1 : ∀ [EquivBEq.{u} α] [LawfulHashable.{u} α], Std.DHashMap.Internal.Raw.WFImp.{u, v} m), motive m ⋯) →
    (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {c : Nat},
        motive ↑(Std.DHashMap.Internal.Raw₀.emptyWithCapacity.{u, v} c) ⋯) →
      (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
          {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β a}
          (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
          motive ↑(Std.DHashMap.Internal.Raw₀.insert.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a b) ⋯) →
        (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
            {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β a}
            (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
            motive ↑(Std.DHashMap.Internal.Raw₀.containsThenInsert.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a b).2
              ⋯) →
          (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
              {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β a}
              (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
              motive
                ↑(Std.DHashMap.Internal.Raw₀.containsThenInsertIfNew.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a
                      b).2
                ⋯) →
            (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
                {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α}
                (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                motive ↑(Std.DHashMap.Internal.Raw₀.erase.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a) ⋯) →
              (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
                  {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β a}
                  (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                  motive ↑(Std.DHashMap.Internal.Raw₀.insertIfNew.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a b)
                    ⋯) →
                (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] [inst_3 : LawfulBEq.{u} α]
                    {m : Std.DHashMap.Raw.{u, v} α β}
                    {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β a}
                    (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                    motive
                      ↑(Std.DHashMap.Internal.Raw₀.getThenInsertIfNew?.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a
                            b).2
                      ⋯) →
                  (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] {m : Std.DHashMap.Raw.{u, v} α β}
                      {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))}
                      {f : (a : α) → β a → Bool} (a : Std.DHashMap.Raw.WF.{u, v} m),
                      motive ↑(Std.DHashMap.Internal.Raw₀.filter.{u, v} f (Subtype.mk.{max (v + 1) (u + 1)} m h)) ⋯) →
                    (∀ {β : Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α]
                        {m : Std.DHashMap.Raw.{u, v} α fun x => β}
                        {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α} {b : β}
                        (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                        motive
                          ↑(Std.DHashMap.Internal.Raw₀.Const.getThenInsertIfNew?.{u, v}
                                (Subtype.mk.{max (v + 1) (u + 1)} m h) a b).2
                          ⋯) →
                      (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α] [inst_3 : LawfulBEq.{u} α]
                          {m : Std.DHashMap.Raw.{u, v} α β}
                          {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α}
                          {f : β a → β a} (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                          motive ↑(Std.DHashMap.Internal.Raw₀.modify.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a f)
                            ⋯) →
                        (∀ {β : Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α]
                            {m : Std.DHashMap.Raw.{u, v} α fun x => β}
                            {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α}
                            {f : β → β} (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                            motive
                              ↑(Std.DHashMap.Internal.Raw₀.Const.modify.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a
                                  f)
                              ⋯) →
                          (∀ {β : α → Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α]
                              [inst_3 : LawfulBEq.{u} α] {m : Std.DHashMap.Raw.{u, v} α β}
                              {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α}
                              {f : Option.{v} (β a) → Option.{v} (β a)} (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                              motive
                                ↑(Std.DHashMap.Internal.Raw₀.alter.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h) a f)
                                ⋯) →
                            (∀ {β : Type v} [inst : BEq.{u} α] [inst_2 : Hashable.{u + 1} α]
                                {m : Std.DHashMap.Raw.{u, v} α fun x => β}
                                {h : LT.lt.{0} 0 (Array.size.{max u v} (Std.DHashMap.Raw.buckets.{u, v} m))} {a : α}
                                {f : Option.{v} β → Option.{v} β} (a_1 : Std.DHashMap.Raw.WF.{u, v} m),
                                motive
                                  ↑(Std.DHashMap.Internal.Raw₀.Const.alter.{u, v} (Subtype.mk.{max (v + 1) (u + 1)} m h)
                                      a f)
                                  ⋯) →
                              motive a t
